"use strict";

// Hardcoded model URL used for fetching model.json and related chunks
const modelUrl = "https://paddlejs.cdn.bcebos.com/models/fuse/facedetect_opt/model.json";

class FetchModel {
  constructor(url) {
    this.url = url;
    this.isLocalFile = !this.url.startsWith("http");
    this.inNode = false; // Simplified for browser context
  }

  async fetchModelJson() {
    // Fetch the model.json from the hardcoded URL
    const response = await fetch(this.url);
    if (!response.ok) throw new Error("Failed to fetch model.json");
    return response.json();
  }

  async fetchChunks(chunkNum, dir) {
    // Fetch binary chunks sequentially
    const chunks = [];
    for (let i = 1; i <= chunkNum; i++) {
      const chunkUrl = dir + `chunk_${i}.dat`;
      const chunkResp = await fetch(chunkUrl);
      if (!chunkResp.ok) throw new Error(`Failed to fetch chunk ${i}`);
      const arrayBuffer = await chunkResp.arrayBuffer();
      chunks.push(new Float32Array(arrayBuffer));
    }
    // Concatenate all chunks
    let totalLength = chunks.reduce((acc, c) => acc + c.length, 0);
    let combined = new Float32Array(totalLength);
    let offset = 0;
    for (const chunk of chunks) {
      combined.set(chunk, offset);
      offset += chunk.length;
    }
    return combined;
  }

  async load() {
    const modelJson = await this.fetchModelJson();
    if (modelJson.chunkNum && modelJson.chunkNum > 0) {
      const dir = this.url.substring(0, this.url.lastIndexOf("/") + 1);
      const chunksData = await this.fetchChunks(modelJson.chunkNum, dir);
      // Allocate params data to model vars
      let offset = 0;
      for (const v of modelJson.vars) {
        if (v.persistable) {
          const size = v.shape.reduce((a, b) => a * b, 1);
          v.data = chunksData.slice(offset, offset + size);
          offset += size;
        }
      }
    }
    return modelJson;
  }
}

// Usage example
(async () => {
  const fetcher = new FetchModel(modelUrl);
  const model = await fetcher.load();
  console.log("Model loaded", model);
})();

